// ============================================================
// Node: 2. Normalize WhatsApp Payload  (mode: runOnceForAllItems)
// ------------------------------------------------------------
// Turns raw WhatsApp webhook traffic into clean lead records.
// Accepts:
//   A) WhatsApp Cloud API format  body.entry[].changes[].value.messages[]
//   B) Flat fallback used by WAHA / Evolution-style gateways:
//      { messages: [...] } or a single { from, text|body } object
// Non-message events (delivery / read "statuses") are dropped silently.
// An unreadable payload becomes ONE error item (category "Error" later)
// so the flow logs it instead of crashing mid-run.
// ============================================================
const out = [];

function pushMessage(msg, nameHint) {
  const from = msg.from || msg.remoteJid || msg.phone || '';
  let text = '';
  let type = msg.type || 'text';
  if (msg.text && typeof msg.text.body === 'string') text = msg.text.body;
  else if (typeof msg.body === 'string') text = msg.body; // WAHA-style flat body
  else if (msg.image) { type = 'image'; text = msg.image.caption || ''; }
  else if (msg.video) { type = 'video'; text = msg.video.caption || ''; }
  else if (msg.document) { type = 'document'; text = msg.document.caption || ''; }
  else if (msg.audio) { type = 'audio'; }
  else if (msg.location) { type = 'location'; }

  out.push({
    json: {
      leadId: msg.id || (msg.key && msg.key.id) || `gen-${Date.now()}-${out.length}`,
      phone: String(from),
      name: nameHint || msg.pushName || '',
      text: String(text).trim(),
      msgType: type,
      hasMedia: ['image', 'video', 'audio', 'document'].includes(type),
      timestampSec: msg.timestamp ? Number(msg.timestamp) : null,
      receivedAt: new Date().toISOString(),
    },
  });
}

for (const item of $input.all()) {
  const body = (item.json && item.json.body) || item.json || {};
  try {
    let messagesFound = 0;
    let structureSeen = false;

    // --- Format A: WhatsApp Cloud API ---
    if (Array.isArray(body.entry)) {
      structureSeen = true;
      for (const entry of body.entry) {
        for (const change of entry.changes || []) {
          const value = change.value || {};
          const nameByWaId = {};
          for (const c of value.contacts || []) {
            nameByWaId[c.wa_id] = (c.profile && c.profile.name) || '';
          }
          for (const m of value.messages || []) {
            pushMessage(m, nameByWaId[m.from] || '');
            messagesFound++;
          }
          // value.statuses = sent/delivered/read receipts -> ignored on purpose
        }
      }
    }

    // --- Format B: flat gateway payloads ---
    if (messagesFound === 0 && Array.isArray(body.messages)) {
      structureSeen = true;
      for (const m of body.messages) { pushMessage(m, ''); messagesFound++; }
    }
    if (messagesFound === 0 && !structureSeen && (body.text || body.body || body.from || body.phone)) {
      pushMessage(
        { from: body.from || body.phone || '', type: 'text',
          text: { body: body.text || body.body || '' }, timestamp: body.timestamp },
        ''
      );
      messagesFound++;
      structureSeen = true;
    }

    if (!structureSeen) {
      out.push({
        json: {
          _error: 'unrecognized_payload',
          detail: 'No messages array found in payload keys: ' + Object.keys(body).join(','),
          receivedAt: new Date().toISOString(),
        },
      });
    }
    // Recognized structure with zero messages (e.g. status-only webhook)
    // intentionally produces no item.
  } catch (e) {
    out.push({
      json: {
        _error: 'parse_exception',
        detail: String(e && e.message ? e.message : e),
        receivedAt: new Date().toISOString(),
      },
    });
  }
}

return out;

// ============================================================
// Node: 3. Score & Route Lead  (mode: runOnceForAllItems)
// ------------------------------------------------------------
// Lead scoring + reply routing for LOCAL SERVICE businesses
// (auto repair / beauty / real estate / hotels), the verticals
// channel partners actually sell WhatsApp automation to.
//
// What this node decides for every incoming WhatsApp lead:
//   score / category (Hot >= 70, Warm >= 45, Cold) + reasons
//   within24h  - Meta's 24-hour free-form window still open?
//   openNow    - inside configured business hours?
//   replyMode  - "freeform" (inside window) or "template" (window
//                expired -> only a pre-approved template may reopen)
//   replyText  - ready-to-send draft, category + hours aware
//   action     - alert_owner (Hot) / auto_reply / log_only (Error)
//
// >>> BUYER CONFIG: edit the block below per business. <<<
const CONFIG = {
  vertical: 'auto', // auto | beauty | realestate | hotel | generic
  businessName: 'Your Business Name',
  openHour: 9,
  closeHour: 21,
  tzOffsetHours: 8, // business local time = UTC + this offset
  bookingLink: 'https://cal.com/your-business',
};

// Vertical keyword packs. Add the buyer's own language / services here.
const PACKS = {
  auto: {
    service: ['repair', 'engine', 'brake', 'tire', 'tyre', 'oil change', 'inspection',
      'diagnostic', 'battery', 'not starting', 'noise', '修车', '刹车', '轮胎', '机油', '保养', '空调'],
    clarify: 'Could you share your car model and year, and describe the problem?',
  },
  beauty: {
    service: ['haircut', 'hair', 'nails', 'facial', 'massage', 'coloring', 'lash', 'brow',
      '做头发', '美甲', '美容', '按摩', '染发'],
    clarify: 'Which service would you like, and what time suits you best?',
  },
  realestate: {
    service: ['viewing', 'rent', 'buy', 'sell', 'bedroom', 'apartment', 'house', 'condo',
      'lease', '看房', '租房', '买房', '卖房'],
    clarify: 'How many bedrooms do you need, and which area are you looking at?',
  },
  hotel: {
    service: ['room', 'check-in', 'check in', 'stay', 'suite', 'breakfast',
      '订房', '住宿', '房间', '入住'],
    clarify: 'What are your check-in and check-out dates, and how many guests?',
  },
  generic: {
    service: ['service', 'help', 'need', '咨询', '服务'],
    clarify: 'Could you tell me a bit more about what you need?',
  },
};

const BOOKING = ['book', 'appointment', 'schedule', 'reserve', 'booking', '预约', '预订'];
const PRICE = ['price', 'cost', 'how much', 'quote', 'rate', 'charge', '价格', '多少钱', '报价'];
const URGENT = ['urgent', 'asap', 'today', 'right now', 'emergency', 'broken', 'leaking',
  'stuck', '急', '今天', '现在', '马上'];
const TIMEFRAME = ['tomorrow', 'this week', 'this weekend', 'tonight', 'next week',
  '明天', '这周', '今晚', '下周'];
const INFOQ = ['open', 'hours', 'where', 'location', 'address', '开门', '几点', '地址', '在哪'];
const GREETINGS = ['hi', 'hello', 'hey', 'yo', 'hola', '你好', '您好'];

function scoreLead(lead, nowMs) {
  if (lead._error) {
    return Object.assign({}, lead, {
      score: 0, category: 'Error', reasons: [lead._error],
      within24h: false, openNow: false, replyMode: 'none',
      replyText: '', action: 'log_only',
    });
  }

  const pack = PACKS[CONFIG.vertical] || PACKS.generic;
  const rawText = lead.text || '';
  const text = rawText.toLowerCase();
  const hit = (list) => list.some((w) => text.includes(w));

  let score = 25;
  const reasons = [];
  if (hit(BOOKING)) { score += 25; reasons.push('booking intent'); }
  if (hit(PRICE)) { score += 20; reasons.push('asks price'); }
  if (hit(URGENT)) { score += 20; reasons.push('urgent'); }
  if (hit(TIMEFRAME)) { score += 10; reasons.push('timeframe given'); }
  if (hit(pack.service)) { score += 15; reasons.push('names a service (' + CONFIG.vertical + ')'); }
  if (hit(INFOQ)) { score += 5; reasons.push('asks hours/location'); }
  if (rawText.length > 80) { score += 5; reasons.push('detailed message'); }
  if (CONFIG.vertical === 'auto' && lead.hasMedia) {
    score += 10; reasons.push('sent media - likely a job photo');
  }

  // A bare greeting carries no buying signal, however it is phrased.
  const stripped = text.replace(/[!！。.\s]/g, '');
  if (GREETINGS.includes(stripped) || (text.length <= 10 && reasons.length === 0)) {
    score = Math.min(score, 35);
    if (!reasons.includes('greeting only')) reasons.push('greeting only');
  }
  score = Math.min(score, 100);
  const category = score >= 70 ? 'Hot' : score >= 45 ? 'Warm' : 'Cold';

  // Meta 24-hour window: free-form replies only within 24h of the
  // customer's last message; after that a template must reopen it.
  const within24h = lead.timestampSec
    ? nowMs - Number(lead.timestampSec) * 1000 < 24 * 3600 * 1000
    : true; // no timestamp -> webhook just arrived, treat as fresh
  const replyMode = within24h ? 'freeform' : 'template';

  // Business hours in the business's own timezone.
  const localHour = new Date(nowMs + CONFIG.tzOffsetHours * 3600 * 1000).getUTCHours();
  const openNow = localHour >= CONFIG.openHour && localHour < CONFIG.closeHour;

  const first = (lead.name || '').split(' ')[0];
  const hi = first ? `Hi ${first}! ` : 'Hi! ';
  let replyText;
  if (category === 'Hot') {
    replyText = `${hi}Thanks for reaching out to ${CONFIG.businessName} — this sounds like something we can help with right away. Our team has your message and will confirm shortly. You can also grab a slot here: ${CONFIG.bookingLink}`;
  } else if (category === 'Warm') {
    replyText = `${hi}Thanks for messaging ${CONFIG.businessName}. ${pack.clarify} You can also book directly here: ${CONFIG.bookingLink}`;
  } else {
    replyText = `${hi}Thanks for messaging ${CONFIG.businessName}. We're open ${CONFIG.openHour}:00–${CONFIG.closeHour}:00. Tell us what you need and we'll get right back to you.`;
  }
  if (!openNow) {
    replyText =
      `Thanks for messaging ${CONFIG.businessName} — we're currently closed (open ${CONFIG.openHour}:00–${CONFIG.closeHour}:00). ` +
      (category === 'Hot'
        ? "This looks urgent, so we've alerted the owner right away. "
        : "We'll reply first thing when we open. ") +
      replyText;
  }

  return Object.assign({}, lead, {
    score, category, reasons, within24h, openNow, replyMode, replyText,
    action: category === 'Hot' ? 'alert_owner' : 'auto_reply',
  });
}

const nowMs = Date.now();
return $input.all().map((item) => ({ json: scoreLead(item.json, nowMs) }));

